#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int arrival[100], burst[100], order[100], wait[100], tat[100];
    for (int i = 0; i < n; i++) {
        scanf("%d %d", &arrival[i], &burst[i]);
        order[i] = i;
    }
    /* stable insertion sort by arrival time */
    for (int i = 1; i < n; i++) {
        int k = order[i], j = i - 1;
        while (j >= 0 && arrival[order[j]] > arrival[k]) { order[j + 1] = order[j]; j--; }
        order[j + 1] = k;
    }
    int time = 0;
    for (int x = 0; x < n; x++) {
        int i = order[x];
        if (time < arrival[i]) time = arrival[i];   /* CPU idle */
        wait[i] = time - arrival[i];
        time += burst[i];
        tat[i] = time - arrival[i];
    }
    double sw = 0, st = 0;
    for (int i = 0; i < n; i++) {
        printf("P%d waiting=%d turnaround=%d\n", i + 1, wait[i], tat[i]);
        sw += wait[i]; st += tat[i];
    }
    printf("Average waiting=%.2f\n", sw / n);
    printf("Average turnaround=%.2f\n", st / n);
    return 0;
}

