#include <stdio.h>

int main(void) {
    int n, q;
    if (scanf("%d %d", &n, &q) != 2) return 0;
    int burst[100], rem[100], finish[100], order[100], done = 0;
    int queue[100000], head = 0, tail = 0;
    for (int i = 0; i < n; i++) {
        scanf("%d", &burst[i]);
        rem[i] = burst[i];
        queue[tail++] = i;
    }
    int time = 0;
    while (head < tail) {
        int i = queue[head++];
        int run = rem[i] < q ? rem[i] : q;
        time += run;
        rem[i] -= run;
        if (rem[i] == 0) { finish[i] = time; order[done++] = i; }
        else queue[tail++] = i;
    }
    printf("Order:");
    for (int k = 0; k < n; k++) printf(" P%d", order[k] + 1);
    printf("\n");
    double total = 0;
    for (int i = 0; i < n; i++) {
        int w = finish[i] - burst[i];
        printf("P%d waiting=%d turnaround=%d\n", i + 1, w, finish[i]);
        total += w;
    }
    printf("Average waiting=%.2f\n", total / n);
    return 0;
}

