#include <stdio.h>
#include <string.h>

int main(void) {
    int frames, n;
    char algo[8];
    if (scanf("%d %7s", &frames, algo) != 2) return 0;
    scanf("%d", &n);
    int pages[1000];
    for (int i = 0; i < n; i++) scanf("%d", &pages[i]);

    int lru = strcmp(algo, "LRU") == 0;
    int mem[100], count = 0, hits = 0;   /* mem[0] = next victim */
    for (int i = 0; i < n; i++) {
        int p = pages[i], pos = -1;
        for (int j = 0; j < count; j++) if (mem[j] == p) { pos = j; break; }
        if (pos >= 0) {
            hits++;
            if (lru) {   /* move to the end: most recently used */
                for (int j = pos; j < count - 1; j++) mem[j] = mem[j + 1];
                mem[count - 1] = p;
            }
        } else {
            if (count == frames) {   /* evict mem[0] */
                for (int j = 0; j < count - 1; j++) mem[j] = mem[j + 1];
                count--;
            }
            mem[count++] = p;
        }
    }
    printf("Hits: %d\nFaults: %d\n", hits, n - hits);
    return 0;
}

