#include <stdio.h>

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;
    int work[10], max[50][10], alloc[50][10], done[50] = {0}, seq[50];
    for (int j = 0; j < m; j++) scanf("%d", &work[j]);
    for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) scanf("%d", &max[i][j]);
    for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) scanf("%d", &alloc[i][j]);

    for (int count = 0; count < n; count++) {
        int pick = -1;
        for (int i = 0; i < n && pick < 0; i++) {
            if (done[i]) continue;
            int ok = 1;
            for (int j = 0; j < m; j++)
                if (max[i][j] - alloc[i][j] > work[j]) { ok = 0; break; }
            if (ok) pick = i;
        }
        if (pick < 0) { printf("UNSAFE\n"); return 0; }
        for (int j = 0; j < m; j++) work[j] += alloc[pick][j];
        done[pick] = 1;
        seq[count] = pick;
    }
    printf("SAFE:");
    for (int k = 0; k < n; k++) printf(" P%d", seq[k]);
    printf("\n");
    return 0;
}

