#include <stdio.h>

int main(void) {
    char mode[8];
    while (scanf("%7s", mode) == 1) {
        char out[10];
        for (int i = 0; i < 3; i++) {
            int v = mode[i] - '0';
            out[i * 3]     = (v & 4) ? 'r' : '-';
            out[i * 3 + 1] = (v & 2) ? 'w' : '-';
            out[i * 3 + 2] = (v & 1) ? 'x' : '-';
        }
        out[9] = '\0';
        printf("%s %s\n", mode, out);
    }
    return 0;
}
